import{_ as i}from"./chunks/img.Dck1PxLc.js";import{_ as e,C as a,c as o,o as t,j as n,G as l,a0 as r,a as s}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Informazioni sulla Pétanque Academy","description":"","frontmatter":{},"headers":[],"relativePath":"it/about.md","filePath":"it/about.md"}');const u=e({name:"it/about.md"},[["render",function(e,c,u,p,d,m){const g=a("AdBanner"),h=a("AdInArticle");return t(),o("div",null,[c[0]||(c[0]=n("h1",{id:"informazioni-sulla-petanque-academy",tabindex:"-1"},[s("Informazioni sulla Pétanque Academy "),n("a",{class:"header-anchor",href:"#informazioni-sulla-petanque-academy","aria-label":'Permalink to "Informazioni sulla Pétanque Academy"'},"​")],-1)),l(g),c[1]||(c[1]=r('<h2 id="la-passione-per-la-boccia" tabindex="-1">La passione per la boccia <a class="header-anchor" href="#la-passione-per-la-boccia" aria-label="Permalink to &quot;La passione per la boccia&quot;">​</a></h2><p>Benvenuti alla Pétanque Academy, dove una profonda passione per la pétanque è la nostra forza trainante da oltre 45 anni. Il mio percorso in questo sport è stato fatto di dedizione, abilità e continuo entusiasmo.</p><p>La pétanque non è solo un gioco; è un modo per connettersi, elaborare strategie e godersi la vita all&#39;aria aperta, e ho avuto la fortuna di sperimentarne le molteplici sfaccettature per quasi mezzo secolo. Che si tratti del posizionamento preciso di una boccia o del cameratismo sul campo, il mio impegno per la pétanque rimane più forte che mai.</p><p><img src="'+i+'" alt="Patrik Wiik with friends"></p><p><em>Condividere questa passione con gli amici è ciò che rende la pétanque così speciale. Le innumerevoli ore trascorse sul campo, tra risate, sana competizione e storie condivise, creano legami che durano una vita.</em></p><hr><h2 id="la-mia-missione" tabindex="-1">La mia missione <a class="header-anchor" href="#la-mia-missione" aria-label="Permalink to &quot;La mia missione&quot;">​</a></h2><p>La missione della Pétanque Academy è aiutare i giocatori d&#39;élite a liberare il loro pieno potenziale, affrontando il gioco mentale, l&#39;aspetto spesso trascurato che distingue i buoni giocatori da quelli grandi.</p><p>Attraverso questo sito condivido:</p><ul><li><strong>Strutture di gioco mentale</strong> sviluppate da decenni di esperienza</li><li><strong>Strumenti e modelli pratici</strong> per la definizione degli obiettivi e la formazione</li><li><strong>Metodologie di workshop</strong> per costruire la sicurezza psicologica</li><li><strong>Approcci basati sull&#39;evidenza</strong> per le prestazioni sotto pressione</li></ul><p>Non si tratta di un allenamento tecnico, ma di creare le basi mentali che consentano alle tue competenze tecniche di emergere quando più conta.</p><hr><h2 id="perche-ho-creato-questo-sito" tabindex="-1">Perché ho creato questo sito <a class="header-anchor" href="#perche-ho-creato-questo-sito" aria-label="Permalink to &quot;Perché ho creato questo sito&quot;">​</a></h2><p>Dopo oltre 45 anni di gioco delle bocce, ho visto innumerevoli giocatori di talento avere difficoltà non con la tecnica, ma con:</p><ul><li><strong>Critico interiore</strong> che distrugge la fiducia dopo gli errori</li><li><strong>Pressione</strong> che li fa giocare in modo diverso in competizione</li><li><strong>Mancanza di struttura</strong> nell&#39;allenamento mentale</li><li><strong>Isolamento</strong> nel loro percorso di sviluppo</li></ul><p>Questo sito esiste per cambiare le cose. Ogni contenuto è progettato per essere immediatamente pratico: modelli da copiare, framework da applicare subito e strumenti che funzionano in situazioni di competizione reale.</p><hr>',17)),l(h),c[2]||(c[2]=r('<h2 id="contattaci" tabindex="-1">Contattaci <a class="header-anchor" href="#contattaci" aria-label="Permalink to &quot;Contattaci&quot;">​</a></h2><p>Mi piacerebbe molto sentire la tua opinione! Se hai domande, vuoi condividere la tua esperienza o sei interessato a workshop e corsi di formazione, non esitare a contattarmi.</p><h3 id="informazioni-sui-contatti" tabindex="-1">Informazioni sui contatti <a class="header-anchor" href="#informazioni-sui-contatti" aria-label="Permalink to &quot;Informazioni sui contatti&quot;">​</a></h3><p><strong>Email:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="aiutami-a-migliorare-questo-sito" tabindex="-1">Aiutami a migliorare questo sito <a class="header-anchor" href="#aiutami-a-migliorare-questo-sito" aria-label="Permalink to &quot;Aiutami a migliorare questo sito&quot;">​</a></h2><p>Il tuo feedback è prezioso! Questo sito è in continua evoluzione, in base alle reali esigenze dei giocatori d&#39;élite.</p><h3 id="mi-piacerebbe-sentire-la-tua-opinione-su" tabindex="-1">Mi piacerebbe sentire la tua opinione su: <a class="header-anchor" href="#mi-piacerebbe-sentire-la-tua-opinione-su" aria-label="Permalink to &quot;Mi piacerebbe sentire la tua opinione su:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Cosa ti aiuterebbe di più?</p><ul><li><p><strong>Quali contenuti vorresti vedere di più?</strong></p><ul><li>Altre tecniche di gioco mentale?</li><li>Modelli più pratici?</li><li>Casi di studio di giocatori d&#39;élite?</li></ul></li><li><p><strong>Cosa manca nel sito?</strong></p><ul><li>Argomenti non trattati?</li><li>Quali strumenti vorresti che esistessero?</li><li>Risorse che non riesci a trovare?</li></ul></li><li><p><strong>Cosa funziona bene?</strong></p><ul><li>Quali pagine ti sono state più utili?</li><li>Quali strumenti hai effettivamente utilizzato?</li><li>Cosa ha fatto la differenza più grande per te?</li></ul></li><li><p><strong>Come posso migliorarlo?</strong></p><ul><li>Miglioramenti alla navigazione?</li><li>Organizzazione dei contenuti?</li><li>Altri esempi?</li><li>Formati diversi?</li></ul></li></ul></div><h3 id="inviami-il-tuo-feedback" tabindex="-1">Inviami il tuo feedback <a class="header-anchor" href="#inviami-il-tuo-feedback" aria-label="Permalink to &quot;Inviami il tuo feedback&quot;">​</a></h3><p><strong>Invia i tuoi pensieri via email a:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Suggerimenti per la riga dell&#39;oggetto:</strong></p><ul><li>&quot;Feedback sul sito: [Il tuo argomento]&quot;</li><li>&quot;Richiesta di contenuto: [Cosa ti serve]&quot;</li><li>&quot;Storia di successo: [Come ha aiutato]&quot;</li><li>&quot;Suggerimento: [La tua idea]&quot;</li></ul><p><strong>Cosa includere:</strong></p><ul><li>Il tuo livello/esperienza attuale</li><li>A cosa stai lavorando</li><li>Feedback o richieste specifiche</li><li>Eventuali storie di successo che utilizzano il contenuto</li></ul><hr><h2 id="cosa-dicono-gli-altri" tabindex="-1">Cosa dicono gli altri <a class="header-anchor" href="#cosa-dicono-gli-altri" aria-label="Permalink to &quot;Cosa dicono gli altri&quot;">​</a></h2><details class="details custom-block"><summary>Feedback dei giocatori d&#39;élite</summary><p><em>&quot;I contenuti del mental game hanno cambiato completamente il mio approccio alla competizione. Solo il framework Inner Coach ha valso la scoperta di questo sito.&quot;</em> — Campione regionale, Francia</p><p><em>&quot;Finalmente qualcuno che capisce che la tecnica non è il problema. La metodologia del workshop ha offerto al nostro club un modo completamente nuovo di allenarsi.&quot;</em> — Giocatore della nazionale svedese</p><p><em>&quot;Il modello di obiettivo e il modello di diario sono esattamente ciò di cui avevo bisogno. Semplici, pratici e realmente utilizzabili.&quot;</em> — Giocatore del torneo, Spagna</p></details><hr><h2 id="informazioni-sul-contenuto" tabindex="-1">Informazioni sul contenuto <a class="header-anchor" href="#informazioni-sul-contenuto" aria-label="Permalink to &quot;Informazioni sul contenuto&quot;">​</a></h2><p>Tutti i contenuti di questo sito sono:</p><ul><li><strong>Gratuito e accessibile</strong> - Nessun paywall, nessun contenuto nascosto</li><li><strong>Pratici e attuabili</strong> - Modelli che puoi utilizzare oggi</li><li><strong>Basato su prove</strong> - Basato sulla ricerca psicologica e su oltre 45 anni di esperienza</li><li><strong>Aggiornamento continuo</strong> - Nuovi contenuti aggiunti in base al tuo feedback</li></ul><hr><h2 id="privacy-e-cookie" tabindex="-1">Privacy e cookie <a class="header-anchor" href="#privacy-e-cookie" aria-label="Permalink to &quot;Privacy e cookie&quot;">​</a></h2><p>Questo sito utilizza Google AdSense per supportare il suo funzionamento. Utilizzando questo sito, accetti l&#39;utilizzo dei cookie da parte di Google per la personalizzazione degli annunci e l&#39;analisi.</p><p><strong>Rispettiamo la tua privacy:</strong></p><ul><li>Non vengono raccolti dati personali oltre alle analisi standard</li><li>Nessuna mailing list o spam</li><li>Le informazioni di contatto vengono utilizzate solo per rispondere ai tuoi messaggi</li></ul><hr><h2 id="connetti-e-condividi" tabindex="-1">Connetti e condividi <a class="header-anchor" href="#connetti-e-condividi" aria-label="Permalink to &quot;Connetti e condividi&quot;">​</a></h2><p>Se ritieni che questo contenuto sia utile:</p><ul><li><strong>Condividilo</strong> con i tuoi compagni di allenamento</li><li><strong>Consiglialo</strong> al tuo club</li><li><strong>Collegamento</strong> dalle tue risorse</li><li><strong>Fornisci feedback</strong> per aiutarci a migliorare</li></ul><p>Insieme possiamo elevare il gioco mentale della pétanque in tutto il mondo.</p><hr>',34)),l(g),c[3]||(c[3]=n("p",null,[n("strong",null,"Grazie per aver fatto parte della Pétanque Academy!")],-1)),c[4]||(c[4]=n("p",null,[n("em",null,"— Patrik Wiik")],-1))])}]]);export{c as __pageData,u as default};
